import { useEffect, useState } from "react";
import axios from "axios";
import Swal from "sweetalert2";
import "./admin.css";

export default function AdminPanel() {
  const [productos, setProductos] = useState([]);
  const [pedidos, setPedidos] = useState([]);
  const [form, setForm] = useState({
    nombre: "",
    descripcion: "",
    precio: "",
    categoria: "",
    imagen: null
  });

  const API_URL = "https://backend-cozyhome.onrender.com/api";
  const token = localStorage.getItem("token");

  const cargarProductos = async () => {
    try {
      const res = await axios.get(`${API_URL}/products`);
      setProductos(res.data);
    } catch (error) {
      Swal.fire("Error", "Error cargando productos", "error");
    }
  };

  const cargarPedidos = async () => {
    try {
      const res = await axios.get(`${API_URL}/sales`);
      setPedidos(res.data);
    } catch (error) {
      Swal.fire("Error", "Error cargando pedidos", "error");
    }
  };

  const handleChange = (e) =>
    setForm({ ...form, [e.target.name]: e.target.value });

  const handleImagen = (e) =>
    setForm({ ...form, imagen: e.target.files[0] });

  const agregarProducto = async (e) => {
    e.preventDefault();

    const formData = new FormData();
    Object.keys(form).forEach(key => {
      formData.append(key, form[key]);
    });

    try {
      await axios.post(`${API_URL}/products`, formData, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "multipart/form-data"
        }
      });

      setForm({
        nombre: "",
        descripcion: "",
        precio: "",
        categoria: "",
        imagen: null
      });

      cargarProductos();
      Swal.fire("Éxito", "Producto agregado correctamente", "success");
    } catch (error) {
      Swal.fire("Error", "Error creando producto", "error");
    }
  };

  const eliminarProducto = async (id) => {
    const confirm = await Swal.fire({
      title: "¿Eliminar producto?",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#c0564b",
      cancelButtonColor: "#6a9b74",
      confirmButtonText: "Sí, eliminar"
    });

    if (!confirm.isConfirmed) return;

    await axios.delete(`${API_URL}/products/${id}`, {
      headers: { Authorization: `Bearer ${token}` }
    });

    cargarProductos();
  };

  const cambiarEstado = async (id_sale, estado) => {
    await axios.put(`${API_URL}/sales/${id_sale}`, { estado });
    cargarPedidos();
  };

  useEffect(() => {
    cargarProductos();
    cargarPedidos();
  }, []);

  return (
    <div className="admin-panel">
      <div className="container">

        <h2>Panel de Administración</h2>

        <h4>Agregar producto</h4>

        <form onSubmit={agregarProducto}>
          <input className="form-control mb-2" name="nombre" placeholder="Nombre" value={form.nombre} onChange={handleChange} required />
          <textarea className="form-control mb-2" name="descripcion" placeholder="Descripción" value={form.descripcion} onChange={handleChange} required />
          <input className="form-control mb-2" type="number" name="precio" placeholder="Precio" value={form.precio} onChange={handleChange} required />
          <input className="form-control mb-2" name="categoria" placeholder="Categoría" value={form.categoria} onChange={handleChange} required />
          <input className="form-control mb-2" type="file" onChange={handleImagen} required />

          {form.imagen && (
            <img
              src={URL.createObjectURL(form.imagen)}
              alt="preview"
              width="120"
              className="mb-3"
            />
          )}

          <button className="btn btn-success w-100">
            Agregar producto
          </button>
        </form>

        <table className="table">
          <thead>
            <tr>
              <th>Nombre</th>
              <th>Precio</th>
              <th>Imagen</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {productos.map(p => (
              <tr key={p.id}>
                <td>{p.nombre}</td>
                <td>${p.precio}</td>
                <td><img src={p.imagen} width="70" alt="" /></td>
                <td>
                  <button
                    className="btn btn-danger btn-sm"
                    onClick={() => eliminarProducto(p.id)}
                  >
                    Eliminar
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        <h4 className="mt-5">Pedidos</h4>

        <table className="table">
          <thead>
            <tr>
              <th>ID</th>
              <th>Usuario</th>
              <th>Total</th>
              <th>Estado</th>
              <th>Productos</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {pedidos.length === 0 ? (
              <tr>
                <td colSpan="6" className="text-center">
                  No hay pedidos
                </td>
              </tr>
            ) : (
              pedidos.map(p => (
                <tr key={p.id_sale}>
                  <td>{p.id_sale}</td>
                  <td>{p.identificacion_usuario}</td>
                  <td>${Number(p.total).toLocaleString("es-CO")}</td>
                  <td>{p.estado}</td>
                  <td>
                    {p.detalles.map(d => (
                      <div key={d.id_detail}>
                        {d.nombre_producto} x {d.cantidad}
                      </div>
                    ))}
                  </td>
                  <td>
                    <button
                      className={`btn btn-sm ${p.estado === "pendiente" ? "btn-success" : "btn-warning"}`}
                      onClick={() =>
                        cambiarEstado(
                          p.id_sale,
                          p.estado === "pendiente" ? "completada" : "pendiente"
                        )
                      }
                    >
                      Cambiar estado
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>

      </div>
    </div>
  );
}
